            //
            aOrbiterE = (((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 39U)) + 0xF1DD64EBC53694F6ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
