            aWandererB = aWandererB ^ (((RotL64(aCross, 43U) + RotL64(aOrbiterF, 47U)) + aOrbiterJ) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 11U) + RotL64(aOrbiterE, 29U)) + aOrbiterK) + aTwistWandererUpdateSaltD[((aIndex + 15U)) & S_SALT1]);
