            aOrbiterF = (aWandererH + RotL64(aScatter, 3U)) + 0x1BE3729FD17ACAD6ULL;
            aOrbiterC = (aWandererJ + RotL64(aPrevious, 13U)) + 0xA5031602F0F6B989ULL;
            aOrbiterK = ((aWandererD + RotL64(aIngress, 37U)) + 0x285CF839BE381C42ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aCross, 29U)) + RotL64(aCarry, 37U)) + 0xBB4CB483C5E4CB0BULL;
            aOrbiterG = (((aWandererE + RotL64(aIngress, 53U)) + RotL64(aCarry, 51U)) + 0xDC0C7C907C267182ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterI = ((aWandererG + RotL64(aScatter, 60U)) + RotL64(aCarry, 21U)) + 0xBAEE8668BB140F0DULL;
            aOrbiterJ = (aWandererA + RotL64(aPrevious, 23U)) + 0x5897F17C70641C21ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x26697251238E2A0BULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x7D45E86EEC2F5BB9ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x78B73DB58F5702E9ULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xBB4E86C0EB923E1EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xD766ADB311751AD0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xDDF810A873ECAB05ULL), 19U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0xE27A06BE136C9257ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 13U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xE83A9F258ABCD5B6ULL;
