            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0xD50754B9B89C7BABULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0xB01D111AD855A239ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x456E7664706EDD27ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x0E7B14D31C17F10AULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0x2B2E22A2CA727AFAULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x0350B7D083336BBBULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xD590E08B869285F7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x63183CDB9334319DULL;
            aOrbiterI = RotL64((aOrbiterI * 0x03737B0507F54C6BULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x2C4C85EC3406A88BULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0xBC9026E063890665ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x8F4297BF7EF93809ULL), 51U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterC, 13U);
