            //
            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 11064U)) & S_BLOCK1], 54U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 11510U)) & S_BLOCK1], 29U));
            aCross ^= RotL64(pSnowLaneC[((aIndex + 14102U)) & S_BLOCK1], 39U);
