            aOrbiterG = ((aWandererD + RotL64(aScatter, 41U)) + RotL64(aCarry, 41U)) + 0xB6AA9CF6483D9D47ULL;
            aOrbiterH = (aWandererF + RotL64(aPrevious, 23U)) + 0x9A8946D8E1CC5EB0ULL;
