            //
            aOrbiterA = ((aWandererC + RotL64(aCross, 41U)) + 0xD21D1E9DF7DF03D0ULL) + aTwistOrbiterAssignSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = ((aWandererE + RotL64(aPrevious, 27U)) + RotL64(aCarry, 27U)) + 0xEB71934D3C4702C1ULL;
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 35U)) + RotL64(aCarry, 47U)) + 0x16358F6ED4E076E8ULL;
            aOrbiterK = (aWandererJ + RotL64(aIngress, 20U)) + 0xFD38D5A1327F1B9DULL;
            aOrbiterD = (aWandererI + RotL64(aScatter, 47U)) + 0x126D27C898708256ULL;
            aOrbiterE = (aWandererH + RotL64(aCross, 11U)) + 0x7E0778FD5F21674FULL;
            aOrbiterF = (((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 5U)) + 0xB2076CE153104D45ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x7796FED4C1435AA4ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0xF96AD0B2A11B450DULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
