            aOrbiterE = RotL64((aOrbiterE * 0xED9D2832E96631C5ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x54A0975D2DEA58D6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x22FB2B0DDF69BD16ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9D83B88D91271AEFULL), 29U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x2380D6BCD87A5932ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x82384A2D411665E1ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6560B37489A67BC1ULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x0141AA76A2A320E3ULL;
