            aOrbiterG = (aWandererE + RotL64(aScatter, 51U)) + 0x869C7584C18E2A0BULL;
            aOrbiterF = (((aWandererD + RotL64(aPrevious, 43U)) + RotL64(aCarry, 11U)) + 0x5D501041DDA7D873ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aCross, 21U)) + RotL64(aCarry, 51U)) + 0xCFB8CA17A824F5F2ULL;
