        for (std::size_t aIndex = 0U; aIndex < static_cast<std::size_t>(S_BLOCK); aIndex += 1U) {
            //
            aPrevious = aIngress;
            //
            aIngress = (RotL64(aPoisonLaneA[((aIndex + 3211U)) & S_BLOCK1], 38U) ^ RotL64(aPoisonLaneB[((aIndex + 3761U)) & S_BLOCK1], 51U));
            aIngress ^= (RotL64(aKeyRowReadB[((aIndex + 7053U)) & W_KEY1], 3U) ^ RotL64(aIceLaneB[((S_BLOCK1 - aIndex + 2708U)) & S_BLOCK1], 21U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 5059U)) & S_BLOCK1], 43U) ^ RotL64(aLightningLaneD[((S_BLOCK1 - aIndex + 6653U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 7619U)) & W_KEY1], 13U) ^ RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 3995U)) & S_BLOCK1], 54U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 51U) ^ RotL64(aPrevious, 11U)) + (RotL64(aCross, 37U) ^ RotL64(aIngress, 24U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterH = (aWandererI + RotL64(aIngress, 43U)) + 0x29F5FA3BAA18D78AULL;
            aOrbiterK = ((aWandererK + RotL64(aPrevious, 3U)) + RotL64(aCarry, 53U)) + 0x1DBA112DBF73F93CULL;
            aOrbiterA = ((aWandererD + RotL64(aScatter, 37U)) + RotL64(aCarry, 39U)) + 0x613E762FCE653B7EULL;
            aOrbiterG = (((aWandererA + RotL64(aCross, 57U)) + RotL64(aCarry, 5U)) + 0x679C52479F68FC62ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 10U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aIngress, 26U)) + 0xAFBAD8F023CFB163ULL;
            aOrbiterE = ((aWandererC + RotL64(aCross, 19U)) + 0xD1BB7082160E4925ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aPrevious, 11U)) + 0xB94D65F65A6760F7ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x8BED6B29934CF911ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0xBEF8F66BD354C049ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x3A4923580E05F05BULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xD91DFDA41D4264ABULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0xE4C4813EE5C1E1CEULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x1B4C770D015A0977ULL), 13U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x2C27173DD4433679ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xAB0ECD405F7B8866ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB42FBCCBB1BDC06DULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xF50E3CD8A3297DFCULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0xF8938B0632446112ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x394F8CF4EFA14E79ULL), 29U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x4C056930DBB26702ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x2A9C88449317CB91ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB4B88B4C8796E9E7ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x2F4A115D15F0122EULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x50350D4EB6705855ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF45EBDE57AADED87ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x3C95AC69C1967F23ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xA20406E68B2F8E40ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA7012F7186F4A1BDULL), 3U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterK, 53U);
            aIngress = aIngress + (RotL64(aOrbiterE, 35U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterB, 13U));
            aIngress = aIngress + RotL64(aOrbiterG, 47U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererD = aWandererD + (((RotL64(aCross, 35U) + RotL64(aOrbiterA, 3U)) + aOrbiterB) + RotL64(aCarry, 35U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 3U) + aOrbiterK) + RotL64(aOrbiterH, 35U));
            aWandererK = aWandererK + (((RotL64(aScatter, 51U) + aOrbiterH) + RotL64(aOrbiterG, 41U)) + aKeyRotateWandererUpdateSaltF[((aIndex + 26U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 29U) + RotL64(aOrbiterE, 29U)) + aOrbiterG) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aIngress, 22U) + RotL64(aOrbiterB, 47U)) + aOrbiterE);
            aWandererC = aWandererC ^ ((RotL64(aCross, 43U) + aOrbiterH) + RotL64(aOrbiterE, 20U));
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 13U) + aOrbiterA) + RotL64(aOrbiterI, 57U)) + RotL64(aCarry, 13U));
            //
            aCarry = aCarry + (RotL64(aWandererD, 38U) ^ aWandererA);
            aCarry = aCarry + (RotL64(aWandererC, 53U) ^ aWandererI);
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererK, 23U));
            aCarry = aCarry + RotL64(aWandererB, 11U);
            aCarry = aCarry + RotL64(aIngress, 29U);
            aCarry = TwistMix64::DiffuseC(aCarry);
            //
            aShadowLaneA[aIndex] = aIngress;
        }
    
        //
        // grow_a_loop_a loop 2
        //
        // Ingress:
        //      aShadowLaneA (-->), aPoisonLaneC (-->), aLightningLaneC (-->), aPlasmaLaneC (<-?->)
        //
        // Cross:
        //      aPoisonLaneA (<--), aPoisonLaneD (<--), aMagmaLaneB (<--), aSoilLaneA (<-?->)
        //
        // Destination:
        //      aShadowLaneB
