        for (std::size_t aIndex = 0U; aIndex < static_cast<std::size_t>(S_BLOCK); aIndex += 1U) {
            //
            aPrevious = aIngress;
            //
            aIngress = (RotL64(aShadowLaneA[((aIndex + 15018U)) & S_BLOCK1], 11U) ^ RotL64(aPoisonLaneC[((aIndex + 16363U)) & S_BLOCK1], 28U));
            aIngress ^= (RotL64(aLightningLaneC[((aIndex + 15313U)) & S_BLOCK1], 57U) ^ RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 14971U)) & S_BLOCK1], 43U));
            aIngress = TwistMix64::DiffuseA(aIngress);
            //
            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 12502U)) & S_BLOCK1], 19U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 8982U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 11227U)) & S_BLOCK1], 56U) ^ RotL64(aSoilLaneA[((aIndex + 8999U)) & S_BLOCK1], 37U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 29U) + RotL64(aPrevious, 57U)) + (RotL64(aIngress, 11U) ^ RotL64(aCross, 42U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterB = ((aWandererI + RotL64(aPrevious, 5U)) + RotL64(aCarry, 5U)) + 0x3889CB0A4A759A34ULL;
            aOrbiterG = (aWandererC + RotL64(aIngress, 43U)) + 0x81E254E79D1F5A76ULL;
            aOrbiterH = (((aWandererB + RotL64(aCross, 11U)) + RotL64(aCarry, 23U)) + 0xA281A7BDC33D15CBULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aScatter, 37U)) + RotL64(aCarry, 43U)) + 0x53C589DD13657EFAULL;
            aOrbiterF = (aWandererD + RotL64(aIngress, 27U)) + 0xA9AB12B0CA664BD9ULL;
            aOrbiterD = (aWandererK + RotL64(aCross, 21U)) + 0x448C7A8C1276B9EDULL;
            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 50U)) + 0x4F8D13BA57D2B629ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 3U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x73DEB80A71918936ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x69DDC9F59218721FULL;
            aOrbiterH = RotL64((aOrbiterH * 0xBBBB337F2717F479ULL), 3U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x64F331B44A8EC927ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xDA28B710C350AF76ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x8817563452D36D3BULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xAC783977932150E4ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x41E67F60947F4F73ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF8E9C451301C79A5ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0xFD3A222985F14428ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xAB6E291F239D336AULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x23B5BAE6A98BEC9DULL), 53U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x4385C25F70FA0876ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x8E42A23C66FB510EULL;
            aOrbiterG = RotL64((aOrbiterG * 0xB6779CFC1FB39629ULL), 39U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0xB66304519618EFA3ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xEC6B157575B5011DULL;
            aOrbiterK = RotL64((aOrbiterK * 0xDE4C5217AECE8E4DULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x437DB4F7EC7E3C4EULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0xB35A5DD22DC8EE5EULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xCFBC2BF23D622437ULL), 23U);
            //
            aIngress = RotL64(aOrbiterG, 30U) ^ aOrbiterJ;
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterD, 47U));
            aIngress = aIngress + (RotL64(aOrbiterK, 11U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterH, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ ((RotL64(aScatter, 11U) + RotL64(aOrbiterG, 35U)) + aOrbiterD);
            aWandererC = aWandererC + (((RotL64(aPrevious, 26U) + RotL64(aOrbiterD, 51U)) + aOrbiterJ) + RotL64(aCarry, 43U));
            aWandererB = aWandererB ^ ((RotL64(aCross, 19U) + RotL64(aOrbiterH, 13U)) + aOrbiterK);
            aWandererK = aWandererK + (((RotL64(aIngress, 57U) + RotL64(aOrbiterK, 6U)) + aOrbiterB) + RotL64(aCarry, 3U));
            aWandererD = aWandererD ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterK, 19U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aPrevious, 39U) + aOrbiterJ) + RotL64(aOrbiterG, 57U));
            aWandererI = aWandererI ^ (((RotL64(aIngress, 47U) + aOrbiterD) + RotL64(aOrbiterF, 29U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 12U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererD, 35U));
            aCarry = aCarry + (RotL64(aWandererK, 53U) ^ aWandererH);
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererI, 46U));
            aCarry = aCarry + RotL64(aWandererE, 41U);
            aCarry = aCarry + RotL64(aIngress, 5U);
            aCarry = TwistMix64::DiffuseB(aCarry);
            //
            aShadowLaneB[S_BLOCK1 - aIndex] = aIngress;
        }
    
        //
        // grow_a_loop_a loop 3
        //
        // Ingress:
