            //
            aOrbiterI = ((aWandererG + RotL64(aScatter, 29U)) + RotL64(aCarry, 43U)) + 0xDC0D07673663CF66ULL;
            aOrbiterD = (aWandererE + RotL64(aCross, 38U)) + 0xF97E09D175371F61ULL;
            aOrbiterH = (aWandererF + RotL64(aIngress, 47U)) + 0x88C3EDCD5A501DB3ULL;
            aOrbiterC = (aWandererH + RotL64(aPrevious, 13U)) + 0x7B75B5EDEEE9786AULL;
            aOrbiterG = (((aWandererC + RotL64(aCross, 53U)) + RotL64(aCarry, 29U)) + 0x21CF5A66027317ACULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aIngress, 3U)) + 0x80E684F1843E3B54ULL;
            aOrbiterJ = (((aWandererB + RotL64(aPrevious, 23U)) + RotL64(aCarry, 3U)) + 0x9C1BF66A5489157BULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x8916073A827BC82FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0x0BD534071B58175BULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x90FB102225C1B14FULL), 35U);
