            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xD22D4F4415C67366ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x695D2F501E5B6D59ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD04589BAE4C2E29FULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0xB4D4C42ECADF9D1FULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x4965AE2E1E37F40FULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD8D7060EA7D954ABULL), 23U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0x66B3E26F9C36B19CULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x41F17416D3A5CB58ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC12260FD289AAB47ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x8F13317E056A36AAULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xB916749180DB3A76ULL;
