            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x8C48BBC4843A16E4ULL) + aKeyRotateOrbiterUpdateSaltC[((aIndex + 10U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0x2B0E239DB1ED1207ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xCDB678FD9BD96C75ULL), 29U);
            //
            aIngress = aOrbiterI ^ RotL64(aOrbiterH, 51U);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterG, 43U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterA, 19U));
            aIngress = aIngress + RotL64(aOrbiterC, 5U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ (((RotL64(aCross, 47U) + aOrbiterA) + RotL64(aOrbiterJ, 43U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aScatter, 35U) + RotL64(aOrbiterG, 53U)) + aOrbiterA) + RotL64(aCarry, 35U));
            aWandererC = aWandererC ^ ((RotL64(aIngress, 41U) + aOrbiterD) + RotL64(aOrbiterH, 35U));
            aWandererH = aWandererH + (((RotL64(aPrevious, 10U) + aOrbiterI) + RotL64(aOrbiterC, 13U)) + RotL64(aCarry, 13U));
            aWandererG = aWandererG ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterI, 60U)) + aOrbiterH);
            aWandererD = aWandererD + ((RotL64(aPrevious, 57U) + aOrbiterI) + RotL64(aOrbiterG, 19U));
            aWandererE = aWandererE ^ (((RotL64(aScatter, 21U) + RotL64(aOrbiterJ, 5U)) + aOrbiterG) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1]);
