            aIngress ^= (RotL64(aWoodLaneA[((aIndex + 26793U)) & S_BLOCK1], 5U) ^ RotL64(aIceLaneC[((S_BLOCK1 - aIndex + 25149U)) & S_BLOCK1], 23U));
