            aScatter = (RotL64(aIngress, 43U) ^ RotL64(aCross, 58U)) + (RotL64(aCarry, 11U) ^ RotL64(aPrevious, 27U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterK = (((aWandererK + RotL64(aCross, 51U)) + RotL64(aCarry, 11U)) + 0x95165EBE62876BEBULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = ((aWandererG + RotL64(aIngress, 27U)) + RotL64(aCarry, 53U)) + 0x74D8489410B85B4FULL;
            aOrbiterJ = (aWandererD + RotL64(aPrevious, 10U)) + 0xC5F1090B2405977BULL;
            aOrbiterC = (((aWandererI + RotL64(aScatter, 19U)) + RotL64(aCarry, 35U)) + 0x0B043D062BC9BE62ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 7U)) & S_SALT1];
            aOrbiterF = (aWandererJ + RotL64(aCross, 43U)) + 0x6AE839A5BF5FD5F2ULL;
            aOrbiterD = (aWandererF + RotL64(aPrevious, 57U)) + 0xB79D78B4B2F76329ULL;
            aOrbiterG = (aWandererA + RotL64(aIngress, 35U)) + 0x69E1EC5579BF393EULL;
