            aOrbiterD = RotL64((aOrbiterD * 0x13A674D9D0794F77ULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0x085871454078C408ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x079A39EB99DF8D2DULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE703CAB4CC76167DULL), 43U);
