            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0xA7647AAF42A31DC2ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 24U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x67C746CC3C9DD89AULL;
