            aWandererA = aWandererA + ((RotL64(aIngress, 27U) + RotL64(aOrbiterB, 48U)) + aOrbiterG);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 10U) + aOrbiterA) + RotL64(aOrbiterH, 3U));
