            aWandererG = aWandererG + ((((RotL64(aCross, 43U) + aOrbiterE) + RotL64(aOrbiterC, 21U)) + RotL64(aCarry, 57U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 9U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 19U) + aOrbiterE) + RotL64(aOrbiterJ, 51U));
            aWandererI = aWandererI + ((RotL64(aScatter, 29U) + RotL64(aOrbiterF, 26U)) + aOrbiterI);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 21U) + aOrbiterI) + RotL64(aOrbiterK, 11U));
            aWandererK = aWandererK + ((RotL64(aPrevious, 35U) + RotL64(aOrbiterB, 43U)) + aOrbiterI);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererG, 29U));
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererJ, 39U));
