            //
            aOrbiterA = ((aWandererG + RotL64(aScatter, 6U)) + RotL64(aCarry, 19U)) + 0x11416F138A6C68A1ULL;
            aOrbiterH = ((aWandererA + RotL64(aIngress, 13U)) + RotL64(aCarry, 35U)) + 0x8534DD1170A83949ULL;
