            aOrbiterE = (aWandererB + RotL64(aIngress, 27U)) + 0x7302E89C614A4DB5ULL;
            aOrbiterK = ((aWandererH + RotL64(aCross, 3U)) + 0xCF456238CECAFA14ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aScatter, 43U)) + 0x2D4143E1D1E8A83BULL;
            aOrbiterC = (aWandererF + RotL64(aCross, 11U)) + 0xD89AD061EE229C7EULL;
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 51U)) + 0xC8AB570FE394BFBBULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 4U)) & S_SALT1];
