            aOrbiterG = RotL64((aOrbiterG * 0xFAFE656EDA926D51ULL), 35U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x867134E4061CBA8CULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x42E58E638F614835ULL;
