            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xCAD71F0EC80DC850ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x2A874AA814BBA0BCULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC75664ED199B17BDULL), 21U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x766A80AA75087652ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x731BF7A8D87D3C18ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1777AB5EC19F60B7ULL), 19U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xD4656AE7D88AC912ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xF516759C3776D1BBULL;
            aOrbiterB = RotL64((aOrbiterB * 0x44BB2F17528A6447ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xDB4E7A6B22D768B3ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x4B0F0A1ABB6527ACULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xDCDADAA94059B419ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x1E079254CB98E348ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x92C92CB0E9A47CD8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA856A327B570A883ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x779F3F625CC5C9F4ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x96BA959EFA54F650ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xE3D9B6E760C080C1ULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xF711E4D0615B0C06ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0x72441E652B24E071ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x2CAFAF491AE13EA3ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x3BD297E701D35B81ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x2AE694D0952020B8ULL;
