            aCross ^= (RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 4653U)) & S_BLOCK1], 3U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 4763U)) & S_BLOCK1], 12U));
