            //
            aOrbiterG = ((aWandererE + RotL64(aIngress, 35U)) + RotL64(aCarry, 43U)) + 0xFB2035DA7D9114ACULL;
            aOrbiterI = ((aWandererC + RotL64(aCross, 6U)) + 0x698B281B4711ECBDULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterB = ((aWandererG + RotL64(aPrevious, 29U)) + 0x90611E8D2F2EEE47ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterH = (aWandererF + RotL64(aScatter, 57U)) + 0x917429B253AAA5FCULL;
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 47U)) + RotL64(aCarry, 5U)) + 0xC34B45B5DAA18B18ULL;
            aOrbiterE = (aWandererB + RotL64(aScatter, 21U)) + 0x19E9B222965DC0F5ULL;
