            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x152C57AC577110F8ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0xF8FAABB9ED205852ULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x5BBE1141BB7C56D1ULL), 3U);
            //
