            aIngress = (RotL64(aKineticLaneA[((aIndex + 7464U)) & S_BLOCK1], 19U) ^ RotL64(aAetherLaneC[((aIndex + 9098U)) & S_BLOCK1], 30U));
            aIngress ^= (RotL64(aSoilLaneD[((aIndex + 8939U)) & S_BLOCK1], 39U) ^ RotL64(aWindLaneA[((aIndex + 9502U)) & S_BLOCK1], 57U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 8458U)) & S_BLOCK1], 47U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 5889U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aLightningLaneB[((S_BLOCK1 - aIndex + 8840U)) & S_BLOCK1], 60U) ^ RotL64(aVaporLaneD[((S_BLOCK1 - aIndex + 9873U)) & S_BLOCK1], 19U));
