            aOrbiterJ = RotL64((aOrbiterJ * 0x36E026F9952EF46BULL), 37U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xB9CF5D2F7F772C35ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xB11448DF7B1A3DBBULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2BB1E2EE5A312433ULL), 57U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x5551D7D30E4CAD66ULL) + aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0xD23816F84652A817ULL) ^ aKeySpawnOrbiterUpdateSaltD[((aIndex + 26U)) & S_SALT1];
