            aWandererC = aWandererC ^ (((RotL64(aPrevious, 47U) + RotL64(aOrbiterJ, 11U)) + aOrbiterB) + aKeySpawnWandererUpdateSaltC[(((31U - aIndex) + 24U)) & S_SALT1]);
            //
