            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xA5071C95DF508D6BULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterH) ^ 0x529E7D79D251933CULL) ^ aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xEEB56DF9DED21099ULL), 19U);
