            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xE029CF95ECD50B83ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0xC731E6A511DC3BEFULL) ^ aKeySpawnOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
